-                    ExpectedResponse::Tokenize | ExpectedResponse::Detokenize => {
-                        AbortSource::Local(rid)
-                    }
-                    ExpectedResponse::Generate | ExpectedResponse::Control => {
-                        AbortSource::Guard(rid)
-                    }
-                };
-                let _ = self.abort_tx.send(source);
-            }
-            self.in_flight = false;
-        }
-    }
-}
