-impl ExpectedResponse {
-    fn for_request(kind: &RequestKind) -> Self {
-        match kind {
-            RequestKind::Generate(_) => Self::Generate,
-            RequestKind::Control(_) => Self::Control,
-            RequestKind::Detokenize { .. } => Self::Detokenize,
-            RequestKind::Tokenize { .. } => Self::Tokenize,
